import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForRenal,validRenal,advanceRenal,numericRenal,validRenalPlot,renalLedger,renalSubstances}from './renal-models.js?v=20261023-physicscomplete01';import{showRenal}from './renal-visuals.js?v=20261023-physicscomplete01';export{showRenal};
export function mountRenal(l,p,root,{save,done,feedback}){let ts=tasksForRenal(l.widget.slice(6)),w=p.widget;w.renalTask??=ts[0].id;w.renalDrafts??={};w.renalPassed??=[];let i=ts.findIndex(t=>t.id===w.renalTask);if(i<0)i=0;let t=ts[i],v=w.renalDrafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountRenal(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.renalPassed.includes(t.id));
syncProcessMovie(l,1,['ledger','treatments','losses'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('renalCase','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('renalAnswer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealRenal">Reveal evidence →</button><p id="renalReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showRenal(t.kind,{state:c[0],neutral:t.kind==='ledger',title:t.title,label:c[1],concealed:!r&&t.kind!=='glands',progress:r?1:0,step:r?5:0});$('#renalReadout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validRenal(c,v.answer);}
else if(t.type==='sequence'){body=field('renalNext','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceRenal">Advance pathway →</button><p id="renalReadout" aria-live="polite"></p>';draw=()=>{showRenal(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#renalReadout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}
else if(t.type==='plot'){v.plot??=['','',''];body='<p>Plot the ion amounts from this original supplied table. Each bar uses the same unit scale.</p><table><caption>Supplied sample amounts / units</caption><thead><tr><th>Substance</th><th>Filtered</th><th>Returned</th><th>Remaining</th></tr></thead><tbody>'+renalSubstances.map((n,i)=>'<tr><th>'+n+'</th><td>'+renalLedger.filtered[i]+'</td><td>'+renalLedger.returned[i]+'</td><td>'+renalLedger.remaining[i]+'</td></tr>').join('')+'</tbody></table>'+['Filtered ion bar','Returned ion bar','Remaining ion bar'].map((s,i)=>'<label class="field-label" for="renalPlot'+i+'">'+s+' / units</label><input class="lab-input" id="renalPlot'+i+'" type="number" value="'+v.plot[i]+'">').join('');draw=()=>showRenal('ledger',{title:t.title,plotted:v.plot,label:'Your ion bars; other substances supplied'});valid=()=>validRenalPlot(v.plot);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="renalNumber">Your result / supplied units</label><input class="lab-input" id="renalNumber" type="number" step="any" value="'+(v.number??'')+'">'+field('renalReason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showRenal(t.kind,{title:t.title,label:'Original supplied amounts · not clinical measurements'});valid=()=>numericRenal(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="renalEvidence"></p><div class="lab-actions"><button class="secondary" id="recordRenal">Record reasoning</button><button class="secondary" id="nextRenal">Next challenge →</button></div><p id="renalProgress"></p>';
const status=()=>{$('#renalEvidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.renalPassed.includes(t.id)?'Challenge recorded.':'';$('#renalProgress').textContent=ts.filter(t=>w.renalPassed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id.startsWith('renalPlot')){v.plot[Number(id.slice(-1))]=val;save();draw();return;}if(id==='renalCase'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='renalAnswer')v.answer=val;else if(id==='renalNext')v.next=val;else if(id==='renalNumber')v.number=val;else if(id==='renalReason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{if(e.target.id.startsWith('renalPlot')){v.plot[Number(e.target.id.slice(-1))]=e.target.value;draw();}else v.number=e.target.value;save();};}
if($('#revealRenal'))$('#revealRenal').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validRenal(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validRenal(t.cases[v.case],v.answer));};
if($('#advanceRenal'))$('#advanceRenal').onclick=()=>{let n=advanceRenal(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordRenal').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);let finished=t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.renalPassed.includes(t.id))w.renalPassed.push(t.id);p.widgetDone=ts.every(t=>w.renalPassed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextRenal').onclick=()=>{if(!w.renalPassed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.renalTask=ts[(i+1)%ts.length].id;save();remount();};}
